-- Realistic relational questions over RAG research papers, v2 (2026-10-13): grouped tables, several aggregates,
-- HAVING, top-k, CASE buckets, subqueries; at most one single-number question.
-- Q1: For each retrieval method: how many papers, how many baselines on average, and how many use a reranker?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines, SUM(CASE WHEN uses_reranker = 'Yes' THEN 1 ELSE 0 END) AS with_reranker FROM cspaper GROUP BY retrieval_family;
-- Q2: How many papers are there for each combination of reasoning depth and agent use?
SELECT reasoning_depth, use_agent, COUNT(*) AS papers FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') GROUP BY reasoning_depth, use_agent;
-- Q3: Among agent papers, which frameworks appear at least twice, with their average number of baselines, most used first?
SELECT agent_framework, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper WHERE use_agent = 'Yes' GROUP BY agent_framework HAVING COUNT(*) >= 2 ORDER BY papers DESC;
-- Q4: Which retrieval methods are used by at least 10 papers, ordered by how many baselines they compare on average?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper GROUP BY retrieval_family HAVING COUNT(*) >= 10 ORDER BY average_baselines DESC;
-- Q5: Per application domain: how many papers, how many use a knowledge graph, and how many baselines on average?
SELECT CASE WHEN application_domain LIKE '%Medical%' THEN 'Medical' WHEN application_domain LIKE '%Finance%' THEN 'Finance' WHEN application_domain LIKE '%Education%' THEN 'Education' WHEN application_domain LIKE '%Legal%' THEN 'Legal' ELSE 'General or other' END AS domain, COUNT(*) AS papers, SUM(CASE WHEN uses_knowledge_graph = 'Yes' THEN 1 ELSE 0 END) AS with_knowledge_graph, AVG(baseline_amount) AS average_baselines FROM cspaper GROUP BY domain;
-- Q6: What are the five most used generator models?
SELECT generator_model, COUNT(*) AS papers FROM cspaper WHERE generator_model IS NOT NULL GROUP BY generator_model ORDER BY papers DESC LIMIT 5;
-- Q7: For each reasoning depth, how many papers evaluate on HotpotQA and how many on Natural Questions?
SELECT reasoning_depth, SUM(CASE WHEN evaluation_dataset LIKE '%HotpotQA%' THEN 1 ELSE 0 END) AS on_hotpotqa, SUM(CASE WHEN evaluation_dataset LIKE '%Natural Questions%' THEN 1 ELSE 0 END) AS on_natural_questions FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') GROUP BY reasoning_depth;
-- Q8: For each retrieval method, how many papers study multi-hop and how many single-hop reasoning?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, SUM(CASE WHEN reasoning_depth = 'multi-hop' THEN 1 ELSE 0 END) AS multi_hop, SUM(CASE WHEN reasoning_depth = 'single-hop' THEN 1 ELSE 0 END) AS single_hop FROM cspaper GROUP BY retrieval_family;
-- Q9: How many papers, and how many baselines on average, for each combination of reranker and knowledge graph use?
SELECT uses_reranker, uses_knowledge_graph, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper GROUP BY uses_reranker, uses_knowledge_graph;
-- Q10: Text-only against multimodal papers: how many of each, and how many study multi-hop reasoning?
SELECT CASE WHEN data_modality LIKE '%Image%' OR data_modality LIKE '%Audio%' OR data_modality LIKE '%Video%' THEN 'multimodal' ELSE 'text only' END AS modality, COUNT(*) AS papers, SUM(CASE WHEN reasoning_depth = 'multi-hop' THEN 1 ELSE 0 END) AS multi_hop FROM cspaper GROUP BY modality;
-- Q11: Which retrieval methods do agent papers with multi-turn retrieval use, most common first?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers FROM cspaper WHERE multi_turn_retrieval = 'Yes' AND use_agent = 'Yes' GROUP BY retrieval_family ORDER BY papers DESC;
-- Q12: For each evaluation metric family and reasoning depth, how many papers are there?
SELECT CASE WHEN evaluation_metric LIKE '%EM%' THEN 'exact match' WHEN evaluation_metric LIKE '%F1%' THEN 'F1' WHEN evaluation_metric LIKE '%Accuracy%' THEN 'accuracy' ELSE 'other' END AS metric_family, reasoning_depth, COUNT(*) AS papers FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') GROUP BY metric_family, reasoning_depth;
-- Q13: For agent frameworks with at least three papers, what is the average and the largest number of baselines?
SELECT agent_framework, AVG(baseline_amount) AS average_baselines, MAX(baseline_amount) AS most_baselines FROM cspaper WHERE agent_framework IS NOT NULL GROUP BY agent_framework HAVING COUNT(*) >= 3;
-- Q14: Among multi-hop papers, what is the largest number of baselines per retrieval method?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, MAX(baseline_amount) AS most_baselines FROM cspaper WHERE reasoning_depth = 'multi-hop' GROUP BY retrieval_family;
-- Q15: How many papers compare against more baselines than the average paper, per retrieval method?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers FROM cspaper WHERE baseline_amount > (SELECT AVG(baseline_amount) FROM cspaper) GROUP BY retrieval_family;
-- Q16: For papers with and without agents, how many report HotpotQA results, out of how many papers?
SELECT use_agent, COUNT(performance_on_hotpotqa) AS report_hotpotqa, COUNT(*) AS papers FROM cspaper GROUP BY use_agent;
-- Q17: How many papers use GPT-4o as the generator?
SELECT COUNT(*) AS papers FROM cspaper WHERE generator_model LIKE '%GPT-4o%';
-- Q18: For each retrieval method, how many papers use a GPT model and how many a Llama model as the generator?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, SUM(CASE WHEN generator_model LIKE '%GPT%' THEN 1 ELSE 0 END) AS gpt, SUM(CASE WHEN generator_model LIKE '%Llama%' THEN 1 ELSE 0 END) AS llama FROM cspaper GROUP BY retrieval_family;
-- Q19: Per reasoning depth: average and largest number of baselines, deepest first?
SELECT reasoning_depth, AVG(baseline_amount) AS average_baselines, MAX(baseline_amount) AS most_baselines FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') GROUP BY reasoning_depth ORDER BY average_baselines DESC;
-- Q20: For medical, finance and education papers, which retrieval methods do they use?
SELECT CASE WHEN application_domain LIKE '%Medical%' THEN 'Medical' WHEN application_domain LIKE '%Finance%' THEN 'Finance' ELSE 'Education' END AS domain, CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers FROM cspaper WHERE application_domain LIKE '%Medical%' OR application_domain LIKE '%Finance%' OR application_domain LIKE '%Education%' GROUP BY domain, retrieval_family;
